import json
import random

from supply_guard.catalog import Catalog


def random_catalog(rng):
    catalog = Catalog()
    services = ["api", "worker", rng.choice(["api", "billing", "portal"])]
    services = list(dict.fromkeys(services))
    components = []
    for service in services:
        n = rng.randint(1, 9)
        for _ in range(n):
            ecosystem = rng.choice(["pypi", "pypi", "npm"])
            pkg = f"pkg{rng.randrange(5)}"
            version = f"{rng.randrange(3)}.{rng.randrange(4)}.{rng.randrange(3)}"
            catalog.add_component(service, ecosystem, pkg, version)
            components.append((service, ecosystem, pkg, version))
    components = list(dict.fromkeys(components))

    # Random dependency edges inside each service.
    by_service = {}
    for c in components:
        by_service.setdefault(c[0], []).append(c)
    for service, members in by_service.items():
        for _ in range(rng.randrange(len(members) * 2 + 1)):
            a, b = rng.sample(members, 2)
            try:
                catalog.add_dependency(
                    service, a[1], a[2], a[3],
                    service, b[1], b[2], b[3],
                )
            except ValueError:
                pass

    # Manual vulnerabilities (verbatim names).
    for _ in range(rng.randrange(4)):
        catalog.add_vulnerability(
            f"MAN-{rng.randrange(4)}", f"pkg{rng.randrange(5)}",
            rng.choice(["low", "medium", "high", "critical"]),
        )

    # Imported OSV across two sources; exact-version conditions on PyPI.
    for source in ("nvd", "ghsa"):
        records = []
        for i in range(rng.randrange(4)):
            record = {
                "id": f"CVE-{rng.randrange(4)}",
                "affected": [
                    {
                        "package": {"ecosystem": "PyPI", "name": f"pkg{rng.randrange(5)}"},
                        "versions": [f"{rng.randrange(3)}.{rng.randrange(4)}.{rng.randrange(3)}"],
                    }
                ],
                "database_specific": {
                    "severity": rng.choice(["low", "medium", "high", "critical"])
                },
            }
            records.append(record)
        try:
            catalog.import_osv(source, records)
        except ValueError:
            pass
    return catalog, services


def main():
    rng = random.Random(20261004)
    failures = 0
    for trial in range(400):
        catalog, services = random_catalog(rng)
        all_records = catalog.impact()
        for service in services:
            service_records = catalog.impact(service=service)
            # service scope must equal global filtered
            expect_service = [
                r for r in all_records if r["component"]["service"] == service
            ]
            expect_service.sort(key=lambda r: json.dumps(r, sort_keys=True))
            got_service = sorted(
                service_records, key=lambda r: json.dumps(r, sort_keys=True)
            )
            if expect_service != got_service:
                failures += 1
                print("SERVICE SCOPE MISMATCH", trial, service)
                continue
            # full identity must equal service scope filtered to identity
            identities = {
                (r["component"]["ecosystem"], r["component"]["name"],
                 r["component"]["version"])
                for r in service_records
            }
            for eco, name, ver in identities:
                got = catalog.impact(
                    service=service, ecosystem=eco, name=name, version=ver
                )
                expect = [
                    r for r in service_records
                    if r["component"]["ecosystem"] == eco
                    and r["component"]["name"] == name
                    and r["component"]["version"] == ver
                ]
                if got != expect:
                    failures += 1
                    print(
                        "TARGET MISMATCH", trial, service, eco, name, ver,
                        "\n got  =", json.dumps(got, sort_keys=True),
                        "\n want =", json.dumps(expect, sort_keys=True),
                    )
            # A nonexistent full identity returns []
            miss = catalog.impact(
                service=service, ecosystem="pypi", name="pkgZZZ", version="0.0.0"
            )
            if miss != []:
                failures += 1
                print("MISSING TARGET NOT EMPTY", trial, service, miss)
        catalog.close()
    print("failures:", failures)


if __name__ == "__main__":
    main()

